
#!/bin/bash
set -e

# Consolidates visit-type color coding into one shared source
# (lib/visit-types.js) instead of three independently-drifting
# copies. Fixes a real gap: 'Procedure' and 'Surgery' are both
# legitimate visit types, but the three existing copies each only
# had one of them, so whichever was missing silently fell back to
# grey depending which page you were on. Surgery now gets its own
# distinct color (indigo) rather than sharing teal with Procedure.
# Also added the color badge/dot to two places that previously
# showed visit type as plain text with no color at all
# (Appointments page, Payments' Today's Visits widget).
# Run this from your veda-hmis repo root in Codespaces.

mkdir -p "lib"
echo "" | base64 -d > "lib/visit-types.js"
echo "Wrote lib/visit-types.js"

mkdir -p "app/(main)/doctor-dashboard"
echo "" | base64 -d > "app/(main)/doctor-dashboard/page.js"
echo "Wrote app/(main)/doctor-dashboard/page.js"

mkdir -p "app/(main)/front-office-dashboard"
echo "" | base64 -d > "app/(main)/front-office-dashboard/page.js"
echo "Wrote app/(main)/front-office-dashboard/page.js"

mkdir -p "app/(main)/visits"
echo "" | base64 -d > "app/(main)/visits/page.js"
echo "Wrote app/(main)/visits/page.js"

mkdir -p "app/(main)/appointments"
echo "" | base64 -d > "app/(main)/appointments/page.js"
echo "Wrote app/(main)/appointments/page.js"

mkdir -p "app/(main)/payments"
echo "" | base64 -d > "app/(main)/payments/todays-visits-widget.js"
echo "Wrote app/(main)/payments/todays-visits-widget.js"

git add "lib/visit-types.js" "app/(main)/doctor-dashboard/page.js" "app/(main)/front-office-dashboard/page.js" "app/(main)/visits/page.js" "app/(main)/appointments/page.js" "app/(main)/payments/todays-visits-widget.js"
git commit -m "Consolidate visit-type color coding into one shared source, fix Procedure/Surgery gap, extend to Appointments and Payments widget"
git push

echo "Done."
